CREATE FUNCTION public.audit_book_department() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE dept text; BEGIN IF NEW.kind <> 'book' THEN RETURN NEW; END IF; dept:=NULLIF(NEW.payload->>'department',''); IF dept IS NULL THEN RETURN NEW; END IF; IF TG_OP='INSERT' OR OLD.payload->>'department' IS DISTINCT FROM dept THEN IF NOT EXISTS(SELECT 1 FROM public.book_movements WHERE book_id=NEW.id AND department=dept AND left_at IS NULL) THEN UPDATE public.book_movements SET left_at=now() WHERE book_id=NEW.id AND left_at IS NULL; INSERT INTO public.book_movements(book_id,department,actor_id) VALUES(NEW.id,dept,auth.uid()); END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER record_book_department AFTER INSERT OR UPDATE ON public.erp_records FOR EACH ROW EXECUTE FUNCTION public.audit_book_department();